function renderHeader(){const inside=screen!=='home'&&(state.run&&(state.run.phase!=='ended'||state.run.victoryPending));header.innerHTML=`<div class="game-top-left">${screen==='home'?'<span class="header-wisp">W</span>':`<button class="game-round back-icon" data-action="${['briefing','support'].includes(screen)?'back-route':'exit-menu'}" aria-label="${['briefing','support'].includes(screen)?'Back to route':'Exit to menu'}">${icon('arrow')}</button>`}</div><div class="header-end">${inside?`<button class="bank saved-wallet-bank ember-wallet condensed-wallet" data-action="skills" aria-label="Run build and Packed Light"><span>${condensedIconMarkup()}</span><b>${Math.floor(getSkillWallet(state).condensedGlow||0)}</b><small>PACKED LIGHT</small></button>`:''}${menuButton()}</div>`}
function destroyFlight(){engine?.destroy();engine=null;hud=null;paused=false;document.body.classList.remove('playing');hideLesson()}
function render(view=screen){screen=view;document.body.dataset.screen=screen;document.body.dataset.companionRole=normalizeCompanionRole(roleFleet()[0]);document.body.classList.toggle('playing',screen==='flight');renderHeader();const views={home:renderHome,map:renderMap,briefing:renderBriefing,support:renderSupport,retry:renderRetry,'map-clear':renderMapClear,result:renderResult,victory:renderVictory,'rest-prep':renderRestPrep};app.innerHTML=(views[screen]||renderHome)();if(screen==='map')drawMap();requestAnimationFrame(()=>guideScreen(screen))}
function goToRun(){const r=state.run;if(!r)return render('home');if(r.victoryPending){settleCheckpoint(state);persist();return render('victory')}if(r.phase==='map'&&r.restReady)return render('rest-prep');if(r.phase==='ended'){settleCheckpoint(state);bankRun(state);persist();render('result')}else if(r.phase==='map-clear'){settleCheckpoint(state);persist();render('map-clear')}else render(({map:'map',briefing:'briefing',support:'support',retry:'retry'}[r.phase])||'map')}
function beginRun(replace=false){if((state.run&&(state.run.phase!=='ended'||state.run.victoryPending))&&!replace)return goToRun();closeSheet();destroyFlight();if(state.run?.isTutorial)leaveTutorial(state);if((state.run&&(state.run.phase!=='ended'||state.run.victoryPending)))abandonRun(state);state.run=createRun(state.settings.testOverride?{...state.profile,difficulty:Math.max(6,state.profile.difficulty||1)}:state.profile,undefined,selectedDifficulty);if(state.settings.testOverride)setTestOverride(state,true);setCompanions(state.run,[getStartingCompanion(state)]);fleetSlot=0;treeBranch='main';mainSkillSelection='main-efficiency';persist();goToRun();if(canChooseStartingSkill(state.run))showSkills('main')}
